print(json.dumps(public_library_find_nearby("Los Angeles, CA", ["Wi-Fi", "Children Section"]), indent=4))
print(json.dumps(public_library_find_nearby("Chicago, IL", ["Cafe", "Reading Room"]), indent=4))

